// Layout-triggering properties
let el = document.querySelector(".box");
el.style.width = "200px";  // triggers layout

// Non-layout properties (cheaper)
el.style.color = "red";    // only repaint, no layout

// Batch layout reads and writes
let width = el.offsetWidth;  // READ (forces layout)
el.style.height = width + "px";  // WRITE
// Do all reads first, then all writes!

// ❌ Reflow per iteration (100 reflows!)
for (let i = 0; i < 100; i++) {
  document.querySelector(".list")
    .innerHTML += `<li>Item ${i}</li>`;
}

// ✅ Single reflow with DocumentFragment
let fragment = document.createDocumentFragment();
for (let i = 0; i < 100; i++) {
  let li = document.createElement("li");
  li.textContent = `Item ${i}`;
  fragment.appendChild(li);
}
document.querySelector(".list").appendChild(fragment);  // 1 reflow

// ❌ setTimeout animation (not synced with paint)
function moveBad() {
  element.style.left += "1px";
  setTimeout(moveBad, 16);  // may skip frames!
}

// ✅ rAF animation (synced with browser paint)
function moveGood() {
  element.style.left += "1px";
  requestAnimationFrame(moveGood);  // perfect timing!
}

// Batch updates
function updateItems(items) {
  requestAnimationFrame(() => {
    items.forEach(item => {
      item.style.transform = `translateX(${item.x}px)`;
    });
  });
}
